'use client'

import * as React from 'react'
import { accordionConnect, accordionMachine, cn } from "@/lib/utils"
import { mergeProps, normalizeProps, useMachine } from '@zag-js/react'
import { ChevronDownIcon } from 'lucide-react'

import { Slot } from './slot'

// Context to share state between Accordion and its items
interface AccordionContextValue {
  api: ReturnType<typeof accordionConnect>
  multiple: boolean
}
const AccordionContext = React.createContext<AccordionContextValue | null>(null)

function useAccordion() {
  const context = React.useContext(AccordionContext)
  if (!context) {
    throw new Error('Accordion components must be used within an Accordion')
  }
  return context
}

interface AccordionProps extends React.HTMLAttributes<HTMLDivElement> {
  type?: 'single' | 'multiple'
  collapsible?: boolean
  defaultValue?: string | string[]
  value?: string | string[]
  onValueChange?: (value: string | string[]) => void
  disabled?: boolean
}

const toArray = (value?: string | string[] | null, multiple?: boolean) => {
  if (value == null) return undefined
  if (Array.isArray(value)) return value
  return value === '' ? [] : [value]
}

const toValue = (value: string[], multiple: boolean) => {
  if (multiple) return value
  return value[0] ?? ''
}

const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      className,
      type = 'single',
      collapsible,
      defaultValue,
      value: propValue,
      onValueChange,
      disabled,
      ...props
    },
    ref
  ) => {
    const multiple = type === 'multiple'
    const value = toArray(propValue, multiple)
    const defaultValueArray = toArray(defaultValue, multiple)
    const service = useMachine(accordionMachine, {
      id: React.useId(),
      multiple,
      collapsible,
      disabled,
      value,
      defaultValue: value === undefined ? defaultValueArray : undefined,
      onValueChange: (details) => {
        onValueChange?.(toValue(details.value, multiple))
      },
    })
    const api = React.useMemo(() => accordionConnect(service, normalizeProps), [service])
    const contextValue = React.useMemo(() => ({ api, multiple }), [api, multiple])
    const rootProps = api.getRootProps()
    const mergedProps = mergeProps(rootProps, props)

    return (
      <AccordionContext.Provider value={contextValue}>
        <div ref={ref} data-slot="accordion" {...mergedProps} className={cn(className)} />
      </AccordionContext.Provider>
    )
  }
)
Accordion.displayName = 'Accordion'

const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement> & {
    asChild?: boolean
    showChevron?: boolean
    icon?: React.ReactNode
  }
>(({ className, children, asChild = false, showChevron = true, icon, ...props }, ref) => {
  const { api } = useAccordion()
  const item = React.useContext(AccordionItemContext)
  if (!item) throw new Error('Trigger must be within Item')
  const triggerProps = api.getItemTriggerProps({ value: item.value, disabled: item.disabled })

  const Comp = asChild ? Slot : 'button'

  if (asChild) {
    return (
      <Comp
        ref={ref}
        data-slot="accordion-trigger"
        data-state={item.isOpen ? 'open' : 'closed'}
        className={cn(
          'flex flex-1 items-center justify-between py-4 font-medium transition-all hover:underline [&[data-state=open]>svg]:rotate-180',
          className
        )}
        {...mergeProps(triggerProps, props)}
      >
        {children}
      </Comp>
    )
  }

  return (
    <div className="flex">
      <Comp
        ref={ref}
        type="button"
        data-slot="accordion-trigger"
        data-state={item.isOpen ? 'open' : 'closed'}
        className={cn(
          'focus-visible:border-ring focus-visible:ring-ring/50 flex flex-1 items-center justify-between gap-4 rounded-md py-4 text-left text-sm font-semibold transition-all outline-none hover:underline focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&[data-state=open]>svg]:rotate-180',
          className
        )}
        {...mergeProps(triggerProps, props)}
      >
        {children}
        {icon
          ? icon
          : showChevron && (
              <ChevronDownIcon
                size={16}
                className="pointer-events-none shrink-0 opacity-60 transition-transform duration-200"
                aria-hidden="true"
              />
            )}
      </Comp>
    </div>
  )
})
AccordionTrigger.displayName = 'AccordionTrigger'

// Helper for Item Context logic
const AccordionItemContext = React.createContext<{
  value: string
  disabled?: boolean
  isOpen: boolean
} | null>(null)

const AccordionItem = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { value: string; disabled?: boolean }
>(({ className, value, disabled, ...props }, ref) => {
  const { api } = useAccordion()
  const itemState = api.getItemState({ value, disabled })
  const itemProps = api.getItemProps({ value, disabled })
  const mergedProps = mergeProps(itemProps, props)
  const { className: mergedClassName, ...restProps } = mergedProps

  return (
    <AccordionItemContext.Provider value={{ value, disabled, isOpen: itemState.expanded }}>
      <div
        ref={ref}
        data-slot="accordion-item"
        data-state={itemState.expanded ? 'open' : 'closed'}
        className={cn('border-b last:border-b-0', className, mergedClassName)}
        {...restProps}
      />
    </AccordionItemContext.Provider>
  )
})
AccordionItem.displayName = 'AccordionItem'

const AccordionContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => {
    const { api } = useAccordion()
    const item = React.useContext(AccordionItemContext)
    if (!item) throw new Error('Content must be within Item')
    const contentProps = api.getItemContentProps({ value: item.value, disabled: item.disabled })
    const mergedProps = mergeProps(contentProps, props)
    const { className: mergedClassName, ...restProps } = mergedProps

    return (
      <div
        ref={ref}
        data-slot="accordion-content"
        data-state={item.isOpen ? 'open' : 'closed'}
        hidden={!item.isOpen}
        className={cn(
          'overflow-hidden text-sm transition-all',
          item.isOpen ? 'animate-accordion-down' : 'animate-accordion-up',
          className,
          mergedClassName
        )}
        {...restProps}
      >
        <div className="pt-0 pb-4">{children}</div>
      </div>
    )
  }
)
AccordionContent.displayName = 'AccordionContent'

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }

import { createContext } from "../../hooks/create-context"
import type { AccordionApi } from "@/lib/utils"
import type { ComputedRef } from "vue"

export type UseAccordionContext = ComputedRef<AccordionApi>

export const [AccordionProvider, useAccordionContext] = createContext<UseAccordionContext>({
    id: "AccordionContext",
    providerName: "<Accordion />",
})

export type UseAccordionItemContext = ComputedRef<{
    value: string
    disabled?: boolean
    isOpen: boolean
}>

export const [AccordionItemProvider, useAccordionItemContext] = createContext<UseAccordionItemContext>({
    id: "AccordionItemContext",
    providerName: "<AccordionItem />",
})

import { computed, useId } from "vue";
import { normalizeProps, useMachine } from "@zag-js/vue";
import { accordionConnect, accordionMachine } from "@/lib/utils";

export interface UseAccordionProps {
    modelValue?: string | string[];
    defaultValue?: string | string[];
    type?: "single" | "multiple";
    multiple?: boolean;
    collapsible?: boolean;
    disabled?: boolean;
    id?: string;
}

type AccordionEmits = {
    (event: "update:modelValue", value: string | string[]): void;
    (event: "change", value: string | string[]): void;
};

export const useAccordion = (props: UseAccordionProps, emit?: AccordionEmits) => {
    const generatedId = useId();
    const id = props.id ?? generatedId;

    const toArray = (value?: string | string[] | null) => {
        if (value == null) return undefined;
        return Array.isArray(value) ? value : value === "" ? [] : [value];
    };

    const toValue = (value: string[], multiple: boolean) => {
        if (multiple) return value;
        return value[0] ?? "";
    };

    const machineProps = computed(() => {
        const multiple = props.type
            ? props.type === "multiple"
            : !!props.multiple;
        const value = toArray(props.modelValue);
        const defaultValue = toArray(props.defaultValue);
        return {
            id,
            multiple,
            collapsible: props.collapsible,
            disabled: props.disabled,
            value,
            defaultValue: value === undefined ? defaultValue : undefined,
            onValueChange(details: { value: string[] }) {
                const nextValue = toValue(details.value, multiple);
                if (emit) {
                    emit("update:modelValue", nextValue);
                    emit("change", nextValue);
                }
            },
        };
    });

    const service = useMachine(accordionMachine, machineProps);
    return computed(() => accordionConnect(service, normalizeProps));
};

/* Fallback styles */
.space-y-1 > view + view { margin-top: 4px; }
.border-b { border-bottom: 1px solid #e5e5e5; }
.flex { display: flex; }
.flex-1 { flex: 1; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.py-4 { padding-top: 16px; padding-bottom: 16px; }
.pb-4 { padding-bottom: 16px; }
.pt-0 { padding-top: 0; }
.font-medium { font-weight: 500; }
.text-sm { font-size: 14px; }
.overflow-hidden { overflow: hidden; }

/* Animation state */
.closed { display: none; }
.open { display: block; animation: slideDown 0.2s ease-out; }

/* Icon placeholder styling */
.icon-chevron-down {
  width: 10px;
  height: 10px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
  transition: transform 0.2s;
}

.rotate-180 .icon-chevron-down {
   transform: rotate(225deg); /* 180 + 45 */
}

Component({
    relations: {
        '../accordion/index': {
            type: 'parent',
            linked(target) {
                this.parent = target
            },
            unlinked() {
                this.parent = null
            }
        }
    },
    properties: {
        value: {
            type: String,
            value: ''
        },
        disabled: {
            type: Boolean,
            value: false
        },
        className: {
            type: String,
            value: ''
        },
        iconExpandedClass: {
            type: String,
            value: 'rotate-180'
        }
    },
    data: {
        expanded: false
    },
    methods: {
        onTap(e) {
            if (this.data.disabled) return
            if (this.parent) {
                this.parent.handleItemTap(this.data.value)
            }
        }
    }
})
